class MinHeap:
    def __init__(self):
        self._data = []

    def __len__(self):
        return len(self._data)

    def insert(self, value):
        self._data.append(value)
        self._sift_up(len(self._data) - 1)

    def extract_min(self):
        if not self._data:
            raise IndexError("extract_min from empty heap")
        last = self._data.pop()
        if self._data:
            min_val = self._data[0]
            self._data[0] = last
            self._sift_down(0)
            return min_val
        return last

    def _sift_up(self, i):
        while i > 0:
            parent = (i - 1) // 2
            if self._data[i] < self._data[parent]:
                self._data[i], self._data[parent] = self._data[parent], self._data[i]
                i = parent
            else:
                break

    def _sift_down(self, i):
        n = len(self._data)
        while True:
            smallest = i
            left = 2 * i + 1
            right = 2 * i + 2
            if left < n and self._data[left] < self._data[smallest]:
                smallest = left
            if right < n and self._data[right] < self._data[smallest]:
                smallest = right
            if smallest != i:
                self._data[i], self._data[smallest] = self._data[smallest], self._data[i]
                i = smallest
            else:
                break


if __name__ == "__main__":
    import unittest

    class TestMinHeap(unittest.TestCase):
        def test_insert_and_extract(self):
            h = MinHeap()
            h.insert(5)
            h.insert(3)
            h.insert(7)
            h.insert(1)
            self.assertEqual(h.extract_min(), 1)
            self.assertEqual(h.extract_min(), 3)
            self.assertEqual(h.extract_min(), 5)
            self.assertEqual(h.extract_min(), 7)

        def test_extract_min_empty(self):
            h = MinHeap()
            with self.assertRaises(IndexError):
                h.extract_min()

        def test_single_element(self):
            h = MinHeap()
            h.insert(42)
            self.assertEqual(h.extract_min(), 42)
            self.assertEqual(len(h), 0)

        def test_duplicates(self):
            h = MinHeap()
            h.insert(2)
            h.insert(2)
            h.insert(1)
            self.assertEqual(h.extract_min(), 1)
            self.assertEqual(h.extract_min(), 2)
            self.assertEqual(h.extract_min(), 2)

        def test_ascending_insert(self):
            h = MinHeap()
            for v in range(10):
                h.insert(v)
            for expected in range(10):
                self.assertEqual(h.extract_min(), expected)

        def test_descending_insert(self):
            h = MinHeap()
            for v in range(10, 0, -1):
                h.insert(v)
            for expected in range(1, 11):
                self.assertEqual(h.extract_min(), expected)

        def test_len(self):
            h = MinHeap()
            self.assertEqual(len(h), 0)
            h.insert(1)
            h.insert(2)
            self.assertEqual(len(h), 2)
            h.extract_min()
            self.assertEqual(len(h), 1)

    unittest.main()
